293	      renderContainer();
294	
295	      // Computed independently via the SAME real, unmocked mapper this container itself calls —
296	      // proves "verbatim" concretely (same function, same input shape, same output), not just
297	      // that a plausible-looking productId/productName happen to appear somewhere.
298	      // selectCartItemProps' own return type carries an optional productId (CartItemMapperResult,
299	      // matching the SDK's own fully-optional ProductItem type) — both fixtures above always set
300	      // one, so String(...) here is just satisfying that type, not papering over a real gap.
301	      const expectedA = selectCartItemProps({ ...PRODUCT_A, imageGroups: [], variationAttributes: [] });
302	      const expectedB = selectCartItemProps({ ...PRODUCT_B, imageGroups: [], variationAttributes: [] });
303	      const expectedAProductId = String(expectedA.productId);
