1	/**
2	 * SFCC-270 (plan step 2.2). Covers this build's own pass criteria for product-item/index.tsx:
3	 * image renders with an alt, name renders uppercase, price renders, and the colour+size string
4	 * renders as one combined text node (not two separate ones).
5	 *
6	 * Mocks the smallest surface a rendered ProductItem calls transitively (testing.md's own
7	 * guidance), rather than standing up the full commerce-hook dependency chain a real render
8	 * would need (CurrencyContext, CommerceApiProvider, useVariant/useVariationParams/
9	 * useSelectedStore via the real useDerivedProduct, react-intl's IntlProvider via useIntl) —
10	 * this test is about ProductItem's OWN render contract, not re-proving those hooks' own
11	 * correctness, which is out of this file's scope. `use-multi-site` is mocked for the same
12	 * parse-failure-under-Vitest reason item-variant/index.test.tsx's own docblock explains.
13	 *
14	 * SFCC-795 (plan step 3.2) extends this file with the `message` prop's own pass criteria: DOM
15	 * order (message between the stepper and the actions) and the `hasError` wiring into
16	 * `ZimmCartItem`'s recipe. The gap VALUE itself (12px vs 16px token) is proven directly against
17	 * the exported recipe in product-item.css.test.ts, not here — this file's own `HideOnMobile`/
18	 * `HideOnDesktop` both render simultaneously under jsdom (see the existing price-node comment
19	 * below), which is the same underlying fact (jsdom does not evaluate CSS `@media` rules the way
20	 * a real browser does) that makes a `getComputedStyle`/`toHaveStyle` assertion on a
21	 * media-query-scoped `gap` value unreliable here — so the wiring is proven instead via a
22	 * call-args spy on `useMultiStyleConfig` (still the REAL Chakra implementation underneath,
23	 * `shared/ui/useMultiStyleConfig` is a bare re-export of it — confirmed by reading that file —
24	 * so nothing about ProductItem's actual rendering changes; only its call args are observed).
25	 *
26	 * SFCC-795 (plan step 3.3) extends this file with the `discountLabel` prop's own pass criteria:
27	 * omitted renders no node, present renders the exact copy positioned beneath the stepper and
28	 * ahead of `message` (DOM order proven the same compareDocumentPosition way as the message-vs-
29	 * actions test above). The was/now promotional-price mechanism this step also covers is NOT
30	 * tested in this file — it isn't ProductItem's own contract, it's item-price.tsx's (via base
31	 * `display-price`) — see item-variant/index.test.tsx's own new coverage for that, including a
32	 * disclosed limitation on which of item-price.tsx's two branches can actually reach it.
33	 */
34	import React from 'react';
35	import { describe, test, expect, vi, beforeEach } from 'vitest';
36	import { render, screen, fireEvent, waitFor } from '@testing-library/react';
37	import { ChakraProvider } from '@chakra-ui/react';
38	import { IntlProvider } from 'react-intl';
39	import { MemoryRouter } from 'react-router-dom';
40	import theme from 'app/theme';
41	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
42	import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
43	import { useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
44	import { messages as stepperMessages } from 'app/components/ui-kits/molecules/zimmQuantityStepper';
45	import ProductItem from '.';
46	
47	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
48	  default: vi.fn(),
49	}));
50	
51	// SFCC-795: wraps the REAL useMultiStyleConfig (a bare re-export of @chakra-ui/react's own hook —
52	// confirmed in node_modules/@salesforce/retail-react-app/.../shared/ui/useMultiStyleConfig) in a
53	// vi.fn so its call args are inspectable, without changing what it actually returns/does. Lets
54	// the `hasError` wiring test below prove the exact props ProductItem passes through, rather than
55	// asserting a media-query-scoped computed style value jsdom does not reliably resolve (see this
56	// file's own docblock).
57	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async (importOriginal) => {
58	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>();
59	  return {
60	    ...actual,
61	    useMultiStyleConfig: vi.fn(actual.useMultiStyleConfig),
62	  };
63	});
64	
65	// SFCC-271-250 (plan step 3.5): useDerivedProduct is now a controllable vi.fn() (was a static
66	// inline factory returning a fixed quantity) so individual tests can drive ZimmQuantityStepper's
67	// min/max/disabled boundaries at a specific quantity — the same vi.mocked(...) pattern already
68	// used below for useMultiSite/useMultiStyleConfig. Default return value is set in beforeEach.
69	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
70	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
71	  useDerivedProduct: vi.fn(),
72	}));
73	
74	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
75	  useCurrentBasket: () => ({ data: undefined }),
76	}));
77	
78	// item-attributes.tsx imports PromoPopover unconditionally, which imports the base SFCC icons
79	// barrel — that barrel has a top-level side effect (`AmexSymbol.viewBox = ...`) that throws
80	// under Vitest (SVG imports resolve to raw path strings here, not components). Same root cause,
81	// same fix shape, as testing.md's documented ZimmIcon workaround, just via a different import
82	// path (PromoPopover, not ZimmIcon) — not fixable from this test file beyond mocking it away.
83	vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
84	  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
85	}));
86	
87	// SFCC-795 rework (Marcel's own visual checkpoint against the real Figma file): ZimmInlineMessage's
88	// `warning` variant now renders a real ZimmIcon, which hits the same top-level-side-effect gap as
89	// the promo-popover mock above (testing.md's documented "Known gap: ZimmIcon throws under
90	// Vitest"). This file's own "message with variant=\"warning\"" test below renders ProductItem with
91	// a warning message, which now reaches that real (unmocked) icon render for the first time — mocked
92	// at the same smallest surface as footerNavColumn/index.test.tsx / zimmSubscribeSection/index.test.tsx.
93	// Nothing this file asserts on depends on the icon's own content.
94	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
95	  ZimmIcon: (props: { type: string }) => <div data-testid="mock-info-icon" data-type={props.type} />,
96	}));
97	
98	vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
99	  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
100	  return {
101	    ...actual,
102	    usePromotions: () => ({ data: undefined }),
103	    useProducts: () => ({ data: undefined, isLoading: false }),
104	    useProduct: () => ({ data: undefined, isLoading: false }),
105	  };
106	});
107	
108	// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
109	// test is about ProductItem's own render contract (does a combined value render as one node),
110	// not about re-proving getDisplayVariationValues' own correctness. See
111	// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
112	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
113	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
114	  return {
115	    ...actual,
116	    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
117	  };
118	});
119	
120	const mockUseMultiSite = vi.mocked(useMultiSite);
121	const mockUseMultiStyleConfig = vi.mocked(useMultiStyleConfig);
122	const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
123	const mockSetQuantity = vi.fn();
124	
125	// SFCC-271-250: ZimmQuantityStepper's own accessible names (zimmQuantityStepper/index.tsx's
126	// react-intl defaultMessages) — used throughout this file in place of the old, now-removed
127	// ProductQuantityPicker's "Quantity:" label text/input, neither of which renders in this tree
128	// any more. Figma-fidelity audit fix, 2026-09-19: derived from the real, now-exported source
129	// instead of an independently hardcoded copy of the same two strings (a real duplication a
130	// Tester pass found across this file and zimmQuantityStepper/index.test.tsx).
131	const DECREMENT_NAME = stepperMessages.decrement.defaultMessage;
132	const INCREMENT_NAME = stepperMessages.increment.defaultMessage;
133	
134	// ChakraProvider with this project's own theme is required, not optional here — without it,
135	// `textStyle="productNames"`/`"price"`/`"caption"` resolve against Chakra's default (empty)
136	// textStyles, and item-price.tsx's `useBreakpointValue` throws outright reading
137	// `theme.breakpoints` off an undefined theme. Same setup zimmButton's own test uses.
138	const renderWithProviders = (ui: React.ReactElement) =>
139	  render(
140	    <ChakraProvider theme={theme}>
141	      <MemoryRouter>
142	        <IntlProvider locale="en-AU" defaultLocale="en-AU">
143	          {ui}
144	        </IntlProvider>
145	      </MemoryRouter>
146	    </ChakraProvider>,
147	  );
148	
149	const MOCK_LINE_ITEM = {
150	  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
151	  productId: '25595021M',
152	  id: '25595021M',
153	  productName: 'Lilac Sand Silk Midi Dress',
154	  name: 'Lilac Sand Silk Midi Dress',
155	  price: 495,
156	  priceAfterItemDiscount: 495,
157	  pricePerUnit: 495,
158	  quantity: 1,
159	  imageGroups: [
160	    {
161	      viewType: 'small',
162	      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
163	    },
164	  ],
165	};
166	
167	describe('ProductItem', () => {
168	  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
169	  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
170	  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
171	  // own beforeEach.
172	  beforeEach(() => {
173	    Object.defineProperty(window, 'matchMedia', {
174	      writable: true,
175	      value: vi.fn().mockImplementation((query: string) => ({
176	        matches: false,
177	        media: query,
178	        onchange: null,
179	        addListener: vi.fn(),
180	        removeListener: vi.fn(),
181	        addEventListener: vi.fn(),
182	        removeEventListener: vi.fn(),
183	        dispatchEvent: vi.fn(),
184	      })),
185	    });
186	
187	    mockUseMultiSite.mockReturnValue({
188	      site: { id: 'ZimmermannAU' },
189	      buildUrl: (path: string) => path,
190	    });
191	
192	    // SFCC-795: fresh call history per test — mockUseMultiStyleConfig still delegates to the
193	    // real implementation (see the top-of-file vi.mock), this only clears recorded .mock.calls.
194	    mockUseMultiStyleConfig.mockClear();
195	
196	    // SFCC-271-250: default quantity=1 matches every pre-existing test's own assumption (min
197	    // boundary, decrement disabled) — the stepper-boundary and mutation tests further below
198	    // override this per-test with their own mockReturnValue.
199	    mockSetQuantity.mockClear();
200	    mockUseDerivedProduct.mockReturnValue({
201	      stepQuantity: 1,
202	      showInventoryMessage: false,
203	      inventoryMessage: '',
204	      quantity: 1,
205	      setQuantity: mockSetQuantity,
206	    });
207	  });
208	
209	  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
210	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
211	
212	    // Image renders with an alt.
213	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
214	
215	    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
216	    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
217	    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
218	    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
219	    // resolve inherited declarations).
220	    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });
221	
222	    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl.
223	    // Figma-fidelity audit fix, 2026-09-19: previously rendered twice (a real mobile/desktop
224	    // duplicate pair, HideOnDesktop/HideOnMobile-wrapped, both present under jsdom which doesn't
225	    // evaluate CSS media queries) because price was never actually grouped with the name per
226	    // Figma's own "Item Info" spec — it lived in two different places depending on breakpoint.
227	    // Now rendered exactly once, grouped with the name via itemInfo/itemInfoContainer — a real
228	    // structural fix, not just a duplicate-tolerant assertion staying loose around it.
229	    expect(screen.getAllByText('$495.00')).toHaveLength(1);
230	
231	    // The colour+size string renders as ONE text node containing both values — not two
232	    // separate nodes. An exact-string query only matches if both values live in the same node.
233	    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
234	
235	    // Name and price are grouped together (Figma's "Item Info"), separate from colour+size
236	    // (Figma's "Item Description") — proven via DOM ancestry, not just presence. Mutation-tested:
237	    // reverting to the pre-fix structure (price removed from this block) fails this assertion.
238	    const name = screen.getByRole('heading', { level: 2 });
239	    const price = screen.getByText('$495.00');
240	    const colourSize = screen.getByText('Lilac Sand, One size');
241	    const itemInfoGroup = name.closest('div');
242	    expect(itemInfoGroup).toContainElement(price);
243	    expect(itemInfoGroup).not.toContainElement(colourSize);
244	  });
245	
246	  // Round 2 rework, must-fix 4: the gift-card capability slot. Only the capability is asserted
247	  // here — not real gift-card detection, which this build still cannot do (see this component's
248	  // own docblock).
249	  test('hideStepperAndActions suppresses the stepper and every actions surface, and nothing throws', () => {
250	    expect(() =>
251	      renderWithProviders(
252	        <ProductItem
253	          product={MOCK_LINE_ITEM}
254	          primaryAction={<button type="button">Remove</button>}
255	          secondaryActions={<button type="button">Edit</button>}
256	          deliveryActions={<span>Ship to store</span>}
257	          hideStepperAndActions
258	        />,
259	      ),
260	    ).not.toThrow();
261	
262	    // Stepper: SFCC-271-250 swapped ProductQuantityPicker for ZimmQuantityStepper — the absence
263	    // of both its accessible button names proves the stepper itself did not render.
264	    expect(screen.queryByRole('button', { name: DECREMENT_NAME })).not.toBeInTheDocument();
265	    expect(screen.queryByRole('button', { name: INCREMENT_NAME })).not.toBeInTheDocument();
266	
267	    // Actions: primaryAction/secondaryActions/deliveryActions all suppressed.
268	    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
269	    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
270	    expect(screen.queryByText('Ship to store')).not.toBeInTheDocument();
271	
