/**
 * TEMPORARY tester probe — SFCC-11 plan step 4.6 mutation/falsification pass. NOT a permanent
 * suite; deleted at the end of this pass. Exists to answer one question the real suites don't:
 * does the REAL `app/components/product-item` default export actually render correctly with the
 * EXACT merged object cartDrawerContainer.tsx's own render body builds
 * (`{...item, ...fullProduct, price: item.price, quantity: item.quantity, isProductUnavailable}`,
 * cartDrawerContainer.tsx lines ~391-402) — not the already-hand-flattened `MOCK_LINE_ITEM`
 * product-item/index.test.tsx's own suite uses, which never goes through that two-step spread.
 *
 * Mocking recipe copied one-for-one from product-item/index.test.tsx (a proven-working Vitest
 * harness for rendering the REAL ProductItem under jsdom) — only the product fixture differs.
 * `basketLineItem`/`fetchedProduct` field names/shapes are taken directly from
 * commerce-sdk-isomorphic's generated BasketProductItem/Product$0 types (grepped directly, not
 * guessed), and the variationAttributes/variationValues shape is copied from
 * product-item/index.stories.tsx's own MOCK_LINE_ITEM (the one place in this codebase that
 * exercises the REAL getDisplayVariationValues, not a mocked stand-in).
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import ProductItem from 'app/components/product-item';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
  useDerivedProduct: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ data: undefined }),
}));

// item-attributes.tsx imports PromoPopover unconditionally, which imports the base SFCC icons
// barrel — throws under Vitest (testing.md's documented ZimmIcon gap, same root cause).
vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: (props: { type: string }) => <div data-testid="mock-info-icon" data-type={props.type} />,
}));

vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
  };
});

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseDerivedProduct = vi.mocked(useDerivedProduct);

const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

// Real ShopperBasketsV2Types.BasketProductItem fields only (confirmed against
// commerce-sdk-isomorphic/lib/index.esm.d.ts:17366) — no `id`, no `name`, no `imageGroups`,
// no `variationAttributes` exist on this type; those are catalog-Product-only fields.
const basketLineItem = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
