import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ZimmAuthDrawerContent } from './index';
import { useUiCopy } from 'app/hooks/useUiCopy';

// ZimmButton (used by EmailForm and CreateAccount) imports app/components/ui-kits/atoms/zimmIcon,
// which itself imports app/components/icons (the override SVG barrel). That barrel has a top-level
// side effect (AmexSymbol.viewBox = ...) that fails under Vitest's Vite transform. Mocking
// zimmIcon at its root prevents the cascade without needing every icon export listed.
// See footerNavColumn/index.test.tsx for the canonical explanation of this pattern.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

// SocialButtons imports ZimmAppleSignInIcon / ZimmGoogleSignInIcon directly from
// app/components/icons — same SVG barrel as above but reached via a different import specifier.
// Only these two are needed; zimmIcon is mocked separately above so ArrowDownIcon etc. are
// never accessed.
vi.mock('app/components/icons', () => ({
  ZimmAppleSignInIcon: () => null,
  ZimmGoogleSignInIcon: () => null,
}));

// useUiCopy's Provider/fetch logic is covered by its own test. Mocking here isolates this
// suite to ZimmAuthDrawerContent's own render contract — label text is asserted via fallbacks.
vi.mock('app/hooks/useUiCopy', () => ({
  useUiCopy: vi.fn(),
}));

const mockUseUiCopy = vi.mocked(useUiCopy);

const baseProps = {
  emailValue: '',
  onEmailChange: vi.fn(),
  onSendCode: vi.fn(),
  onCreateAccount: vi.fn(),
  socialEnabled: false,
};

describe('ZimmAuthDrawerContent', () => {
  beforeEach(() => {
    mockUseUiCopy.mockReturnValue({ t: (_key: string, fallback: string) => fallback, isLoading: false });
  });

  // Per .claude/rules/testing.md: clear mock call history after each test rather than before
  // the next one — same convention as drawer-menu/index.test.tsx and others.
  afterEach(() => {
    vi.clearAllMocks();
  });

  test('renders the email input and send code button', () => {
    render(<ZimmAuthDrawerContent {...baseProps} />);

    expect(screen.getByRole('textbox', { name: /email/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /send code/i })).toBeInTheDocument();
  });

  test('renders description text when provided', () => {
    render(<ZimmAuthDrawerContent {...baseProps} description="Please log in to continue." />);

    expect(screen.getByText('Please log in to continue.')).toBeInTheDocument();
  });

  test('renders no description when prop is omitted', () => {
    render(<ZimmAuthDrawerContent {...baseProps} />);

    // No free-standing paragraph of description text should be present.
    expect(screen.queryByText(/please log in/i)).not.toBeInTheDocument();
  });

  test('social buttons absent when socialEnabled is false, even with handlers provided', () => {
    render(
      <ZimmAuthDrawerContent
        {...baseProps}
        socialEnabled={false}
        onSignInWithApple={vi.fn()}
        onSignInWithGoogle={vi.fn()}
      />,
    );

    expect(screen.queryByRole('button', { name: /sign in with apple/i })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /sign in with google/i })).not.toBeInTheDocument();
  });

  test('social buttons absent when socialEnabled is true but no handlers provided', () => {
    render(<ZimmAuthDrawerContent {...baseProps} socialEnabled={true} />);

    expect(screen.queryByRole('button', { name: /sign in with apple/i })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /sign in with google/i })).not.toBeInTheDocument();
  });

  test('Apple button renders and fires onSignInWithApple when socialEnabled and handler provided', async () => {
    const onSignInWithApple = vi.fn();
    render(<ZimmAuthDrawerContent {...baseProps} socialEnabled={true} onSignInWithApple={onSignInWithApple} />);

    await userEvent.click(screen.getByRole('button', { name: /sign in with apple/i }));

    expect(onSignInWithApple).toHaveBeenCalledTimes(1);
  });

  test('Google button renders and fires onSignInWithGoogle when socialEnabled and handler provided', async () => {
    const onSignInWithGoogle = vi.fn();
    render(<ZimmAuthDrawerContent {...baseProps} socialEnabled={true} onSignInWithGoogle={onSignInWithGoogle} />);

    await userEvent.click(screen.getByRole('button', { name: /sign in with google/i }));

    expect(onSignInWithGoogle).toHaveBeenCalledTimes(1);
  });

  test('clicking the send code button calls onSendCode when email is valid', async () => {
    const onSendCode = vi.fn();
    render(<ZimmAuthDrawerContent {...baseProps} emailValue="test@example.com" onSendCode={onSendCode} />);

    await userEvent.click(screen.getByRole('button', { name: /send code/i }));

    expect(onSendCode).toHaveBeenCalledTimes(1);
  });

  test('does not resubmit a form-submit event while a request is already in flight', () => {
    const onSendCode = vi.fn();
    render(
      <ZimmAuthDrawerContent {...baseProps} emailValue="test@example.com" onSendCode={onSendCode} isLoading={true} />,
    );

    // isLoading only disables the submit button once React has re-rendered after a previous
    // submission starts — a submit event landing in that window (e.g. a second Enter press or
    // click just before the disabled state paints) must still be rejected by handleSubmit
    // itself, not rely on the button's disabled attribute alone (SFCC-742 review finding).
    // Dispatched directly on the form rather than via userEvent's Enter simulation: jsdom
    // already withholds native implicit submission once the button is actually disabled, so a
    // real keypress can't reach handleSubmit at all here — this test targets handleSubmit's own
    // guard, independent of that browser-native behaviour.
    const form = screen.getByRole('textbox', { name: /email/i }).closest('form');
    expect(form).not.toBeNull();
    fireEvent.submit(form as HTMLFormElement);

    expect(onSendCode).not.toHaveBeenCalled();
  });

  test('create account section renders with heading and fires onCreateAccount on button click', async () => {
    const onCreateAccount = vi.fn();
    render(<ZimmAuthDrawerContent {...baseProps} onCreateAccount={onCreateAccount} />);

    expect(screen.getByText(/new to zimmermann/i)).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: /create an account/i }));

    expect(onCreateAccount).toHaveBeenCalledTimes(1);
  });

  test('uses CMS-resolved labels when useUiCopy returns them', () => {
    mockUseUiCopy.mockReturnValue({
      t: (key: string, fallback: string) => {
        if (key === 'login.drawer.email') return 'E-mail address';
        if (key === 'login.drawer.sendCode') return 'Send my code';
        return fallback;
      },
      isLoading: false,
    });
    render(<ZimmAuthDrawerContent {...baseProps} />);

    expect(screen.getByRole('textbox', { name: 'E-mail address' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Send my code' })).toBeInTheDocument();
  });
});

