}));
vi.mock('app/hooks/useWishlistAuthDrawer', () => ({
  useWishlistAuthDrawer: mockUseWishlistAuthDrawer,
}));

vi.mock('app/components/product-item', () => ({
  default: vi.fn((props: { product: { itemId?: string }; secondaryActions?: React.ReactNode }) => (
    <div data-testid={`mock-product-item-${props.product.itemId ?? ''}`}>{props.secondaryActions}</div>
  )),
}));
vi.mock('app/components/ui-kits/organisms/zimmCartEmptyState', () => ({
  ZimmCartEmptyState: () => <div data-testid="mock-empty-state" />,
}));
vi.mock('app/components/ui-kits/molecules/zimmCartButtonGroup', () => ({
  ZimmCartButtonGroup: () => <div data-testid="mock-button-group" />,
}));
vi.mock('app/components/ui-kits/molecules/zimmCartItemActions', () => ({
  ZimmCartItemActions: (props: {
    productId: string;
    isGuest: boolean;
    onGuestWishlistClick: () => void;
  }) => (
    <div data-testid={`mock-cart-item-actions-${props.productId}`}>
      <button type="button" onClick={props.onGuestWishlistClick}>
        Guest Wishlist Click {props.productId}
      </button>
    </div>
  ),
}));

type SfccBasket = ShopperBasketsV2Types.Basket;
let currentBasket: SfccBasket | undefined;

const PRODUCT_A = { itemId: 'item-a', productId: 'product-a', productName: 'Natura Mini Dress', quantity: 1, price: 495 };

const buildBasket = (productItems: Array<Record<string, unknown>>): SfccBasket =>
  ({ basketId: 'basket-1', lastModified: '2026-09-21T00:00:00.000Z', productItems } as unknown as SfccBasket);

const buildProductsResult = (products: Array<{ id: string; name: string }>) => ({
  data: { data: products.map((p) => ({ id: p.id, name: p.name, imageGroups: [], variationAttributes: [] })), total: products.length },
