  );
};

describe('[TESTER PROBE, temporary] CartWishlistAuthGate — real open/close composition + focus-restore', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });
    currentBasket = buildBasket([PRODUCT_A]);
    mockUseCustomerId.mockReturnValue('customer-1');
    mockUseCustomerType.mockReturnValue({ isRegistered: false });
    mockUseProducts.mockReturnValue(buildProductsResult([{ id: PRODUCT_A.productId, name: PRODUCT_A.productName }]));
    mockUseCustomerProductLists.mockReturnValue({
      data: { data: [{ id: 'wishlist-1', type: 'wish_list', customerProductListItems: [] }], total: 1 },
    });
    mockCapBasketQuantities.mockResolvedValue({ status: 'not-needed' });
    mockUseWishlistAuthDrawer.mockReturnValue(buildWishlistAuthDrawerReturn());
  });

  test('real open -> real content -> real close, and reports what document.activeElement becomes on close', async () => {
    const { rerender } = renderContainer();

    // Real click on the row's guest-wishlist trigger BEFORE the drawer opens — matches real usage
    // (a shopper clicks a row action, which is what's focused at the moment the lock activates)
    // and gives Chakra's own FocusLock a real "previously focused element" candidate to possibly
    // restore to, independent of the manual finalFocusRef mechanism.
    const triggerButton = screen.getByRole('button', { name: 'Guest Wishlist Click product-a' });
    await userEvent.click(triggerButton);
    expect(mockHandleTriggerClick).toHaveBeenCalledTimes(1);
    expect(triggerButton).toHaveFocus();

    // Now actually open the wishlist auth drawer — matching what the real (unmocked)
    // useWishlistAuthDrawer would have driven `triggerRef` to for this container's own
    // document.body-fallback flow (see cartDrawerContainer.tsx's own openGuestWishlistDrawer doc).
    mockUseWishlistAuthDrawer.mockReturnValue(
      buildWishlistAuthDrawerReturn({ isOpen: true, triggerRef: { current: document.body } }),
    );
    rerender(
      <QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}>
        <ChakraProvider theme={theme}>
          <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
        </ChakraProvider>
      </QueryClientProvider>,
    );

    // (a) A second, real dialog with REAL auth content actually appears.
    const wishlistDialog = await screen.findByRole('dialog', { name: 'Wishlist' });
    expect(wishlistDialog).toBeInTheDocument();
    const emailInput = screen.getByRole('textbox', { name: /email/i });
    expect(emailInput).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /send code/i })).toBeInTheDocument();
    // Real ZimmAuthDrawerContent focuses the email input on open (initialFocusRef wiring).
    await waitFor(() => expect(emailInput).toHaveFocus());

    // (b) Close it for real — flip the external isOpen source and let the real exit
    // transition/FocusLock-release/onCloseComplete run (same pattern zimmCartDrawer's own
    // close-focus test uses: real framer-motion transition needs real wall-clock room).
    mockUseWishlistAuthDrawer.mockReturnValue(
      buildWishlistAuthDrawerReturn({ isOpen: false, triggerRef: { current: document.body } }),
    );
    rerender(
      <QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}>
        <ChakraProvider theme={theme}>
          <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
        </ChakraProvider>
      </QueryClientProvider>,
    );

    await waitFor(() => expect(screen.queryByRole('dialog', { name: 'Wishlist' })).not.toBeInTheDocument(), {
      timeout: 3000,
    });
    // Real auth content is genuinely gone, not just the dialog role/name.
    expect(screen.queryByRole('textbox', { name: /email/i })).not.toBeInTheDocument();

    // Sibling agent's open question: does the manual handleCloseComplete mechanism
    // (finalFocusRef.current?.focus(), predicting document.body here) actually win, or does
    // Chakra's own internal FocusLock/ModalFocusScope do something else on its own (e.g. its
    // library-default return-focus-to-previously-focused-element behaviour, which would instead
    // land back on `triggerButton`)? Report which one really happens.
    // eslint-disable-next-line no-console
    process.stdout.write(
      `\n[TESTER PROBE] document.activeElement after wishlist-drawer close: tagName=${document.activeElement?.tagName}, ` +
        `isBody=${document.activeElement === document.body}, isTriggerButton=${document.activeElement === triggerButton}, ` +
        `textContent=${JSON.stringify(document.activeElement?.textContent)}\n`,
    );
  });
});

